"""Render an evidence-led scope and WBS workspace to offline HTML, SVG, JSON and CSV."""
import argparse,base64,csv,html,io,json,sys
from datetime import date
from pathlib import Path

KINDS=('outcome','deliverable','work_package','planning_package')
SCOPE_STATES=('in_scope','proposed_addition','proposed_deferral','planning_package','removed')
MATURITY=('defined','partial','unresolved')
OWNERSHIP=('proposed','confirmed','unknown')
REQ_STATUS=('active','deferred','excluded','open')
EXCLUSION_STATUS=('approved','proposed','disputed')
def esc(x):return html.escape(str(x),quote=True)
def _text(x,k,c,required=True):
 v=x.get(k)
 if not isinstance(v,str) or (required and not v.strip()):raise ValueError(f'{c} {k}: {"nonempty " if required else ""}text required')
def _date(v,c,nullable=False):
 if nullable and v=='':return
 try:
  if date.fromisoformat(v).isoformat()!=v:raise ValueError
 except (TypeError,ValueError):raise ValueError(f'{c}: ISO date YYYY-MM-DD required') from None
def validate(data):
 if not isinstance(data,dict):raise ValueError('Expected a scope-and-WBS snapshot object')
 for k in ('title','version','as_of','source','scope','state','decision_boundary'):_text(data,k,'snapshot')
 _date(data['as_of'],'as_of')
 m=data.get('mandate')
 if not isinstance(m,dict):raise ValueError('mandate is required')
 for k in ('id','version','outcome','authority','approved_on','source'):_text(m,k,'mandate')
 _date(m['approved_on'],'mandate approved_on')
 reqs=data.get('requirements')
 if not isinstance(reqs,list) or not reqs:raise ValueError('requirements must be a nonempty list')
 req_ids=set()
 for r in reqs:
  if not isinstance(r,dict):raise ValueError('Each requirement must be an object')
  for k in ('id','label','status','acceptance','source','note'):_text(r,k,'requirement',required=k!='note')
  if r['id'] in req_ids:raise ValueError(f'duplicate requirement id: {r["id"]}')
  req_ids.add(r['id'])
  if r['status'] not in REQ_STATUS:raise ValueError(f'{r["id"]}: invalid requirement status')
 nodes=data.get('nodes')
 if not isinstance(nodes,list) or not nodes:raise ValueError('nodes must be a nonempty list')
 ids=set()
 for n in nodes:
  if not isinstance(n,dict):raise ValueError('Each WBS node must be an object')
  for k in ('id','label','kind','scope_state','maturity','output','boundary','acceptance','acceptor','owner','ownership_state','estimate_basis','confidence','source','note'):_text(n,k,'node',required=k!='note')
  if n['id'] in ids:raise ValueError(f'duplicate node id: {n["id"]}')
  ids.add(n['id'])
  if n['parent'] is not None and (not isinstance(n['parent'],str) or not n['parent']):raise ValueError(f'{n["id"]}: parent must be null or text')
  if n['kind'] not in KINDS or n['scope_state'] not in SCOPE_STATES or n['maturity'] not in MATURITY or n['ownership_state'] not in OWNERSHIP:raise ValueError(f'{n["id"]}: invalid enumerated value')
  for k in ('source_refs','requirement_ids','inputs','outputs'):
   if not isinstance(n.get(k),list) or any(not isinstance(v,str) or not v.strip() for v in n[k]):raise ValueError(f'{n["id"]}: {k} must be a text list')
 parents={n['id']:n['parent'] for n in nodes}
 for n in nodes:
  if n['parent'] is not None and n['parent'] not in ids:raise ValueError(f'{n["id"]}: unknown parent {n["parent"]}')
  missing=[x for x in n['requirement_ids'] if x not in req_ids]
  if missing:raise ValueError(f'{n["id"]}: unknown requirement IDs: {", ".join(missing)}')
  seen=set();cur=n['id']
  while cur is not None:
   if cur in seen:raise ValueError(f'{n["id"]}: hierarchy contains a cycle')
   seen.add(cur);cur=parents[cur]
 coverage=data.get('coverage')
 if not isinstance(coverage,list):raise ValueError('coverage must be a list')
 seen_links=set()
 for link in coverage:
  if not isinstance(link,dict):raise ValueError('Each coverage link must be an object')
  for k in ('requirement_id','package_id','role','boundary','source'):_text(link,k,'coverage')
  if link['requirement_id'] not in req_ids or link['package_id'] not in ids:raise ValueError('coverage endpoints must exist')
  if link['role'] not in ('primary','support'):raise ValueError('coverage role must be primary or support')
  key=(link['requirement_id'],link['package_id'])
  if key in seen_links:raise ValueError(f'duplicate coverage link: {key[0]} / {key[1]}')
  seen_links.add(key)
 for n in nodes:
  linked={x['requirement_id'] for x in coverage if x['package_id']==n['id']}
  if linked!=set(n['requirement_ids']):raise ValueError(f'{n["id"]}: requirement_ids must match coverage links')
 exclusions=data.get('exclusions')
 if not isinstance(exclusions,list):raise ValueError('exclusions must be a list')
 for x in exclusions:
  for k in ('id','label','basis','authority','status','source'):_text(x,k,'exclusion')
  if x['status'] not in EXCLUSION_STATUS:raise ValueError(f'{x["id"]}: invalid exclusion status')
 events=data.get('events',[])
 if not isinstance(events,list):raise ValueError('events must be a list')
 for ev in events:
  for k in ('id','date','label','state','source'):_text(ev,k,'event')
  _date(ev['date'],f'{ev["id"]} date')
 p=data.get('presentation');a=data.get('analysis')
 if not isinstance(p,dict) or not isinstance(a,dict):raise ValueError('presentation and analysis are required')
 for k in ('eyebrow','headline','lede','default_node_id','decision'):_text(p,k,'presentation')
 if p['default_node_id'] not in ids:raise ValueError('default_node_id must reference nodes')
 for k in ('method','hundred_percent_boundary','overlap_rule','decomposition_rule','authority_boundary'):_text(a,k,'analysis')
 return data
def audit(data,nodes=None):
 rows=data['nodes'] if nodes is None else nodes;row_ids={n['id'] for n in rows};links=[x for x in data['coverage'] if x['package_id'] in row_ids];active={r['id'] for r in data['requirements'] if r['status'] in ('active','deferred')};primary={rid:[x['package_id'] for x in links if x['requirement_id']==rid and x['role']=='primary'] for rid in active}
 return {'coverage_gaps':[rid for rid,v in primary.items() if not v],'overlaps':[rid for rid,v in primary.items() if len(v)>1],'partial':[n['id'] for n in rows if n['maturity']!='defined'],'ownership_gaps':[n['id'] for n in rows if n['ownership_state']!='confirmed'],'proposed_changes':[n['id'] for n in rows if n['scope_state'] in ('proposed_addition','proposed_deferral','removed')],'untraced':[n['id'] for n in rows if not n['source_refs']],'mapped_requirements':sum(bool(v) for v in primary.values()),'active_requirements':len(active)}
def safe(v):
 s='' if v is None else str(v)
 return "'"+s if isinstance(v,str) and s.startswith(('=','+','-','@','\t','\r')) else s
def render_csv(data):
 validate(data);s=io.StringIO(newline='');w=csv.writer(s,lineterminator='\n');w.writerow(['wbs_id','parent','label','kind','scope_state','maturity','output','boundary','acceptance','acceptor','owner','ownership_state','estimate_basis','confidence','source_refs','requirement_ids','inputs','outputs','source','note','as_of','mandate_id','scope_version'])
 for n in data['nodes']:w.writerow([safe(v) for v in [n['id'],n['parent'],n['label'],n['kind'],n['scope_state'],n['maturity'],n['output'],n['boundary'],n['acceptance'],n['acceptor'],n['owner'],n['ownership_state'],n['estimate_basis'],n['confidence'],';'.join(n['source_refs']),';'.join(n['requirement_ids']),';'.join(n['inputs']),';'.join(n['outputs']),n['source'],n['note'],data['as_of'],data['mandate']['id'],data['mandate']['version']]])
 return s.getvalue()
def hierarchy_layout(nodes):
 by={n['id']:n for n in nodes};children={n['id']:[] for n in nodes};roots=[]
 for n in nodes:
  (children[n['parent']] if n['parent'] is not None else roots).append(n['id'])
 pos={};leaf=[0]
 def walk(node,depth):
  kids=children[node]
  if kids:
   ys=[walk(k,depth+1) for k in kids];y=sum(ys)/len(ys)
  else:y=90+leaf[0]*92;leaf[0]+=1
  pos[node]=(60+depth*350,y);return y
 for root in roots:walk(root,0);leaf[0]+=1
 return pos,max(760,170+leaf[0]*92),max(1440,400+max((int((x-60)/350) for x,y in pos.values()),default=0)*350)
def txt(x,y,v,size=13,fill='#13294b',weight='400'):return f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="{size}" fill="{fill}" font-weight="{weight}">{esc(v)}</text>'
def render_svg(data):
 validate(data);a=audit(data);pos,h,w=hierarchy_layout(data['nodes']);colors={'outcome':'#0c234b','deliverable':'#08766c','work_package':'#d80b61','planning_package':'#a25b00'};out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h+380}" viewBox="0 0 {w} {h+380}" role="img" aria-labelledby="title desc">',f'<title id="title">{esc(data["title"])}</title>',f'<desc id="desc">Deliverable hierarchy and scope-control summary as of {esc(data["as_of"])}. Connectors mean part-of, not sequence or effort.</desc>','<rect width="100%" height="100%" fill="#f4f7fb"/><rect width="12" height="100%" fill="#173b2d"/>',txt(38,42,data['presentation']['eyebrow'].upper(),12,'#d80b61','800'),txt(38,96,data['presentation']['headline'],40,'#0c234b','800'),txt(38,130,data['presentation']['lede'],15,'#536581')]
 metrics=[('COVERAGE GAPS',len(a['coverage_gaps'])),('PRIMARY OVERLAPS',len(a['overlaps'])),('PARTIAL',len(a['partial'])),('OWNER GAPS',len(a['ownership_gaps'])),('PROPOSED CHANGES',len(a['proposed_changes']))]
 for i,(k,v) in enumerate(metrics):
  x=38+i*270;out += [f'<rect x="{x}" y="155" width="252" height="78" rx="14" fill="#fff" stroke="#ccd6e5"/>',txt(x+15,178,k,10,'#667085','800'),txt(x+15,211,str(v),22,'#0c234b','800')]
 oy=245
 for n in data['nodes']:
  x,y=pos[n['id']];y+=oy
  if n['parent'] is not None:
   px,py=pos[n['parent']];py+=oy;out.append(f'<path d="M {px+270} {py+29} C {px+310} {py+29}, {x-40} {y+29}, {x} {y+29}" fill="none" stroke="#7890ad" stroke-width="2"/>')
 for n in data['nodes']:
  x,y=pos[n['id']];y+=oy;c=colors[n['kind']]
  out += [f'<rect x="{x}" y="{y}" width="270" height="58" rx="10" fill="#fff" stroke="{c}" stroke-width="2"/>',txt(x+12,y+20,n['id']+' - '+n['kind'].replace('_',' '),10,c,'800'),txt(x+12,y+42,n['label'][:34],12,'#0c234b','800'),txt(x+12,y+54,n['scope_state'].replace('_',' ')[:34],9,'#667085')]
 out += [txt(38,h+oy+70,'Connectors mean part-of, not sequence, effort, authority or dependency.',11,'#536581','800'),txt(38,h+oy+94,data['analysis']['hundred_percent_boundary'][:180],10,'#667085'),'</svg>'];return ''.join(out)
def _json(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
def uri(x,m):return 'data:'+m+';base64,'+base64.b64encode(x.encode()).decode()

